#[repr(C)]
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Bye {
    /// ByeReason
    pub reason: u32,
    pub _pad0: u32,
}

impl Default for Bye {
    fn default() -> Self {
        // SAFETY: only plain integer/float fields, so all-zero bytes are a valid value.
        unsafe { core::mem::zeroed() }
    }
}

// SAFETY: repr(C), plain number fields only, no implicit padding (checked by protogen and below).
unsafe impl crate::Plain for Bye {}

impl crate::Message for Bye {
    const TYPE: MsgType = MsgType::Bye;
}

const _: () = {
    assert!(core::mem::size_of::<Bye>() == 8);
    assert!(core::mem::align_of::<Bye>() == 4);
    assert!(core::mem::offset_of!(Bye, reason) == 0);
    assert!(core::mem::offset_of!(Bye, _pad0) == 4);
};

/// Every HEARTBEAT_EVENT_INTERVAL_MS while connected. Proves the ring works (the header heartbeat proves liveness).
#[repr(C)]
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Heartbeat {
    /// Since this side attached.
    pub uptime_ms: u64,
    /// Game frames this side has run (0 = no frame hook yet).
    pub frames: u64,
}

impl Default for Heartbeat {
    fn default() -> Self {
        // SAFETY: only plain integer/float fields, so all-zero bytes are a valid value.
        unsafe { core::mem::zeroed() }
    }
}

// SAFETY: repr(C), plain number fields only, no implicit padding (checked by protogen and below).
unsafe impl crate::Plain for Heartbeat {}

impl crate::Message for Heartbeat {
    const TYPE: MsgType = MsgType::Heartbeat;
}

const _: () = {
    assert!(core::mem::size_of::<Heartbeat>() == 16);
    assert!(core::mem::align_of::<Heartbeat>() == 8);
    assert!(core::mem::offset_of!(Heartbeat, uptime_ms) == 0);
    assert!(core::mem::offset_of!(Heartbeat, frames) == 8);
};
